    10→// Node is the base interface for all AST nodes
    11→type Node interface {
    12→	TokenLiteral() string
    13→	String() string
    14→}
    15→
    16→// Statement is an interface for statement nodes
    17→type Statement interface {
    18→	Node
    19→	statementNode()
    20→}
    21→
    22→// Expression is an interface for expression nodes
    23→type Expression interface {
    24→	Node
    25→	expressionNode()
    26→}
    27→
    28→// Program represents the root node of the AST
    29→type Program struct {
    30→	Statements []Statement
    31→}
    32→
    33→func (p *Program) TokenLiteral() string {
    34→	if len(p.Statements) > 0 {
    35→		return p.Statements[0].TokenLiteral()
    36→	}
    37→	return ""
    38→}
    39→
    40→func (p *Program) String() string {
    41→	var out strings.Builder
    42→	for _, s := range p.Statements {
    43→		out.WriteString(s.String())
    44→	}
    45→	return out.String()
    46→}
